e":"engagement_score","type":"number","value":"={{ $json.ups }}"}]},"options":{}},"id":"6ccce068-23dc-4446-bebc-859673ce7a6a","name":"Format Reddit Data","type":"n8n-nodes-base.set","position":[320,1488],"typeVersion":3.4},{"parameters":{"url":"https://www.googleapis.com/youtube/v3/search","authentication":"genericCredentialType","genericAuthType":"httpQueryAuth","sendQuery":true,"queryParameters":{"parameters":[{"name":"part","value":"snippet"},{"name":"q","value":"={{ $('Analysis Parameters').item.json.keyword }}"},{"name":"type","value":"video"},{"name":"order","value":"relevance"},{"name":"maxResults","value":"15"},{"name":"publishedAfter","value":"={{ $now.minus({days: 7}).toISO() }}"}]},"options":{}},"id":"d149fea3-9be8-40bc-9c30-cd97305ea52a","name":"YouTube: Search Videos","type":"n8n-nodes-base.httpRequest","position":[128,1664],"typeVersion":4.2},{"parameters":{"fieldToSplitOut":"items","options":{}},"id":"20fb728f-255f-4193-b1b3-e76d6c39c389","name":"Split Out","type":"n8n-nodes-base.splitOut","position":[320,1664],"typeVersion":1},{"parameters":{"operation":"search","searchText":"={{ $json.keyword }}","additionalFields":{}},"id":"d880289a-746c-47d2-93ee-61810a63ce99","name":"X: Search Tweets","type":"n8n-nodes-base.twitter","position":[128,1840],"typeVersion":2},{"parameters":{"mode":"runOnceForEachItem","jsCode":"// 新代码：输出与其他平台完全一致的格式，并增加 engagement_score
try {
  const tweetObject = $input.item.json;

  // 从推文的公开指标(public_metrics)中计算一个综合的互动分数
  // 同时增加安全检查，防止某些指标不存在时报错
  const metrics = tweetObject.public_metrics || {};
  const likeCount = metrics.like_count || 0;
  const retweetCount = metrics.retweet_count || 0;
  const replyCount = metrics.reply_count || 0;
  const quoteCount = metrics.quote_count || 0;
  const engagementScore = likeCount + retweetCount + replyCount + quoteCount;

  // 构建与其他平台格式完全一致的result对象
  const result = {
    source_weight: 0.9,                        // 权重
    source_type: 'twitter',                    // 来源类型
    content: tweetObject.text,                 // 推文内容
    url: `https://x.com/anyuser/status/${tweetObject.id}`, // 推文链接
    engagement_score: engagementScore          // 互动分数
  };

  return { json: result };

} catch (error) {
  console.error('处理推文JSON时出错:', error);
  return { json: { error: '处理推文JSON失败', raw_data: $input.item.json } };
}"},"id":"540c1f48-5fa1-4c21-8c89-e7fc1b8beb82","name":"Parse Twitter Data","type":"n8n-nodes-base.code","position":[320,1840],"typeVersion":2,"alwaysOutputData":false},{"parameters":{"assignments":{"assignments":[{"id":"youtube-weight","name":"source_weight","type":"number","value":0.8},{"id":"youtube-source","name":"source_type","type":"string","value":"youtube"},{"id":"youtube-content","name":"content","type":"string","value":"={{ $json.snippet.title + ' ' + $json.snippet.description }}"},{"id":"youtube-url","name":"url","type":"string","value":"=https://www.youtube.com/watch?v={{ $json.id.videoId }}"},{"id":"youtube-channel","name":"channel","type":"string","value":"={{ $json.snippet.channelTitle }}"}]},"options":{}},"id":"aed5c975-a1f9-4ed1-8e48-aaca903f1976","name":"Format YouTube Data","type":"n8n-nodes-base.set","position":[496,1664],"typeVersion":3.4},{"parameters":{"numberInputs":3},"id":"57025b54-b048-4a8b-bcba-56fd30bd2f15","name":"Merge: All Sources","type":"n8n-nodes-base.merge","position":[720,1680],"typeVersion":3},{"parameters":{"promptType":"define","text":"你是一位敏锐的选题策划，你的任务是为编辑发掘有潜力的内容，而不是过滤信息，同时需要【保留原始内容】。

请根据给定的关键词，为每一条内容进行判断。如果内容满足【以下任一条件】，就必须标记为"YES"，否则标记为"NO"：
1. 包含强烈的个人观点、情绪或独特的个人经历。
2. 引发了争议或多人参与的讨论。
3. 提出了一个新颖的问题或与众不同的见解。
4. 虽然简短，但可能是一个新兴趋势或网络“梗”的苗头。

你的目标是“宁滥勿缺”，只要内容有任何可能成为好选题的火花，都应标记为YES。纯粹的广告或垃圾信息才应标记为NO。

你的回复必须遵循以下规则：
1. 返回一个严格的JSON数组格式的字符串，不要包含任何markdown标记 (如```json)。
2. 该数组的长度必须与输入数组完全一致。
3. 数组中的每个对象都必须包含以下三个字段：
   - `url`: 原始内容的URL。
   - `decision`: 你的判断结果，值为 'YES' 或 'NO'。
   - `content`: 必须原封不动地返回原始内容。

示例输出格式:
[
  { "url": "[http://example.com/article1](http://example.com/article1)", "decision": "YES", "content": "这是第一篇文章的内容..." },
  { "url": "[http://example.com/article2](http://example.com/article2)", "decision": "NO", "content": "这是第二篇文章的内容..." }
]

