// 1. 创建一个空数组，用来存放所有批次解析后的最终结果。
const allParsedItems = [];

// 2. 遍历所有输入的项目（您这里的10个批次）。
//    $input.all() 可以获取全部的输入项。
for (const batchItem of $input.all()) {
  try {
    const contentString = batchItem.json.text;
    if (!contentString) continue; // 如果某个批次的text为空，则跳过

    const cleanedContent = contentString.replace(/```json/g, '').replace(/```/g, '').trim();

    // 3. 解析当前批次中的JSON字符串。
    const itemsInBatch = JSON.parse(cleanedContent);

    // 4. 将解析出的项目（一个数组）添加到我们最终的总结果数组中。
    if (Array.isArray(itemsInBatch)) {
      allParsedItems.push(...itemsInBatch);
    }

  } catch (error) {
    // 如果某个批次解析失败，在控制台打印错误并继续处理下一个批次。
    console.error(`一个批次解析失败。错误: ${error.message}. 批次内容: ${batchItem.json.text}`);
  }
}

// 5. 循环结束后，将包含了所有结果的总数组，格式化成n8n需要的格式并返回。
return allParsedItems.map(item => ({ json: item }));"},"id":"44743863-4809-4500-a47d-b32bb8e8da08","name":"Parse AI Filter Results","type":"n8n-nodes-base.code","position":[1328,1680],"typeVersion":2},{"parameters":{"conditions":{"options":{"version":2,"leftValue":"","caseSensitive":true,"typeValidation":"strict"},"combinator":"and","conditions":[{"id":"filter-condition","operator":{"type":"string","operation":"equals"},"leftValue":"={{ $json.decision }}","rightValue":"YES"}]},"options":{}},"id":"23169519-7abb-41e7-a3e9-f0851da72f45","name":"IF: Is Content Relevant","type":"n8n-nodes-base.if","position":[1520,1680],"typeVersion":2.2},{"parameters":{"jsCode":"try {
