const normalizedTrends = [];

for (const item of $input.all()) {
  const data = item.json;

  // Check if this is News API data
  if (data.articles && Array.isArray(data.articles)) {
    for (const article of data.articles) {
      normalizedTrends.push({
        title: article.title || '',
        description: article.description || article.content || '',
        source: 'NewsAPI',
        url: article.url || '',
        score: 0 // News API doesn't have scores, default to 0
      });
    }
  }

  // Check if this is Reddit data
  if (data.data && data.data.children && Array.isArray(data.data.children)) {
    for (const post of data.data.children) {
      const postData = post.data;
      normalizedTrends.push({
        title: postData.title || '',
        description: postData.selftext || '',
        source: 'Reddit',
        url: postData.url || '',
        score: postData.score || 0
      });
    }
  }
}

return normalizedTrends.map(trend => ({ json: trend }));"},"id":"f38a9e9b-56d6-498d-be75-0e8941f9dce2","name":"Parse and Normalize Trends","type":"n8n-nodes-base.code","typeVersion":2,"position":[928,496]},{"parameters":{"operation":"getAll","dataTableId":{"__rl":true,"mode":"id","value":"<__PLACEHOLDER_VALUE__published_posts_table__>"}},"id":"3e769364-a7c3-41a9-950f-d575ad797546","name":"Check Published Posts History","type":"n8n-nodes-base.dataTable","typeVersion":1,"position":[1152,496]},{"parameters":{"jsCode":"// Filter trends by relevance score, check against published history, and filter by keywords

// Define keywords related to the account topic (customize these based on your niche)
const topicKeywords = ['technology', 'AI', 'artificial intelligence', 'machine learning', 'innovation', 'startup', 'digital', 'software', 'tech'];

// Get normalized trends from previous node
const trends = $input.all().map(item => item.json);

// Get published posts history from Check Published Posts History node
const publishedPosts = $('Check Published Posts History').all().map(item => item.json);

// Create a set of published titles/topics for quick lookup
const publishedTopics = new Set(
  publishedPosts.map(post => (post.title || post.topic || '').toLowerCase())
);

// Filter and score trends
const relevantTrends = trends.filter(trend => {
  const title = (trend.title || '').toLowerCase();
  const description = (trend.description || '').toLowerCase();
  const content = title + ' ' + description;

  // Check if already published (avoid duplicates)
  if (publishedTopics.has(title)) {
    return false;
  }

  // Check for keyword matches
  const keywordMatches = topicKeywords.filter(keyword => 
    content.includes(keyword.toLowerCase())
  ).length;

  // Calculate relevance score (0-100)
  let relevanceScore = 0;

  // Score based on keyword matches (up to 50 points)
  relevanceScore += Math.min(keywordMatches * 15, 50);

  // Score based on engagement if available (up to 30 points)
  const engagement = trend.score || trend.engagement || 0;
  relevanceScore += Math.min(engagement / 100, 30);

  // Score based on recency (up to 20 points)
  if (trend.publishedAt) {
    const hoursAgo = (Date.now() - new Date(trend.publishedAt).getTime()) / (1000 * 60 * 60);
    if (hoursAgo < 24) relevanceScore += 20;
    else if (hoursAgo < 48) relevanceScore += 10;
  }

  // Add relevance score to trend object
  trend.relevanceScore = Math.round(relevanceScore);

  // Only include trends with relevance score >= 50
  return relevanceScore >= 50;
});

// Sort by relevance score (highest first)
relevantTrends.sort((a, b) => b.relevanceScore - a.relevanceScore);

// Return all relevant trends that meet the threshold
return relevantTrends.map(trend => ({ json: trend }));"},"id":"878b96de-5bc0-4c5a-b35b-accb7f316460","name":"Filter Relevant Trends","type":"n8n-nodes-base.code","typeVersion":2,"position":[1376,496]},{"parameters":{"conditions":{"options":{"caseSensitive":false,"leftValue":"","typeValidation":"loose"},"conditions":[{"id":"id-1","leftValue":"={{ $json.relevanceScore }}","rightValue":"50","operator":{"type":"number","operation":"gte"}}],"combinator":"and"},"options":{}},"id":"7600c128-309a-4f73-9944-af449651fe13","name":"Has Relevant Trends?","type":"n8n-nodes-base.if","typeVersion":2,"position":[1600,496]},{"parameters":{"jsCode":"// Parse the OpenAI API response and extract twitter_post and threads_post fields
